package com.fittrack.ultimate;
import android.app.Activity; import android.os.Bundle; import android.webkit.WebSettings; import android.webkit.WebView; import android.webkit.WebViewClient; import android.view.Window;
public class MainActivity extends Activity { @Override public void onCreate(Bundle b){super.onCreate(b); requestWindowFeature(Window.FEATURE_NO_TITLE); WebView w=new WebView(this); w.setWebViewClient(new WebViewClient()); WebSettings s=w.getSettings(); s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setAllowFileAccess(true); s.setBuiltInZoomControls(false); w.loadUrl("file:///android_asset/index.html"); setContentView(w);} @Override public void onBackPressed(){ WebView w=(WebView)findViewById(android.R.id.content).getRootView().findFocus(); if(w instanceof WebView && ((WebView)w).canGoBack()) ((WebView)w).goBack(); else super.onBackPressed(); } }
